#include <bits/stdc++.h>
using namespace std;

#define N 6000
#define MOD 998244353
#define ll long long
#define rep(i, n) for(int i = 0; i < n; ++i)

int main(void) {
	int n, m, k, u, v, sz;
	vector<int>e[N];
	ll x, y, z, s;
	ll dp[N];
	ll dp2[N];

	cin >> n >> m >> k;
	rep(i, m) {
		cin >> u >> v;
		e[u - 1].push_back(v - 1);
		e[v - 1].push_back(u - 1);
	}

	rep(i, n)dp[i] = (ll)0;
	dp[0] = (ll)1;

	rep(i, k) {
		s = (ll)0;
		rep(j, n)s += dp[j];
		rep(j, n) {
			dp2[j] = s - dp[j];
			sz = e[j].size();
			rep(ii, sz)dp2[j] -= dp[e[j][ii]];
			dp2[j] %= MOD;
		}
		rep(j, n)dp[j] = dp2[j];
	}

	cout << dp[0] << endl;

	return 0;
}
